  kart: { baslik: 'Yeni: Hafıza kartları', metin: 'Tahtada ters dönmüş kartlar var. Bir kartın yanında eşleşme yapınca kart açılır ve resmi söylenir. Aynı resimli iki kart açık kalırsa ikisi de toplanır; eşi bulunmayan kart bir hamle sonra yeniden kapanır. Resimleri aklında tut!' },
  hayvan: { baslik: 'Yeni: Çiftlik hayvanları', metin: 'Her hayvan bir meyveyi sever: kirpi çilek, maymun limon, tilki üzüm, tavşan portakal, at elma, ayı erik. Hayvanın yanında sevdiği meyveyi iki kez eşleştir, doysun. Başka meyve işe yaramaz.' },
  recel: { baslik: 'Yeni: Reçel', metin: 'Bu kez engeli temizlemiyor, reçeli yayıyorsun! Reçelli kareye değen ya da onun yanındaki eşleşme, reçeli eşleşmenin karelerine ve hemen yanlarına bulaştırır. Bütün tahtayı reçelle.' },
  fisek: { baslik: 'Yeni: Havai fişek', metin: 'Havai fişeğin yanında eşleşme yap: fişek yukarı fırlar, geçtiği sütunu temizler ve en üstte patlayıp çevresini de temizler.' },
  balik: { baslik: 'Yeni: Balık tutma', metin: 'Balıklar her hamleden sonra bir kare sola yüzer, sol kenardan çıkınca sağdan girer. Oltalı sütunlar işaretli. Balık oltanın sütunundayken yanında eşleşme yaparsan yakalarsın; başka yerde kaçar.' },
  bowling: { baslik: 'Yeni: Bowling', metin: 'Sıranın başındaki bowling topunun yanında eşleşme yapınca top sağa yuvarlanır ve önündeki her şeyi temizler. Labutlar topla, yanlarında eşleşmeyle ya da özel meyveyle devrilir.' },
  pist: { baslik: 'Yeni: Buz pisti', metin: 'Açık mavi kareler kaygan buz pisti. Bir meyveyi pistin üstüne ittiğinde durmaz; aynı yönde pistin bittiği yere ya da kenara kadar kayar, aradaki meyveler birer kare geri gelir.' },
  karanlik: { baslik: 'Yeni: Ateşböcekleri', metin: 'Bahçe karanlık! Yalnız ateşböceklerinin çevresi aydınlık. Ateşböcekleri her hamleden sonra uçup yer değiştirir. Karanlık karelerdeki meyveleri göremezsin ama yine de kaydırabilirsin.' },
  yanki: { baslik: 'Yeni: Yankı mağarası', metin: 'Mağarada her eşleşmenin ortasında bir yankı kalır. İki hamle sonra yankı aynı yerde patlar ve artı şeklinde beş kareyi temizler. Yankıları engellerin yanına düşür!' },
  orumcek: { baslik: 'Yeni: Örümcek ağı', metin: 'Örümcek her üç hamlede bir yakınındaki bir meyveye ağ örer. Ağlı meyve yer değiştiremez; yanında ya da üstünde eşleşme yapınca ağ yırtılır. Örümceğin yanında eşleşme yaparsan örümcek kaçar.' },
  nota: { baslik: 'Yeni: Müzik kutusu', metin: 'Mor karolarda 1 ile 4 arası nota numaraları var. Notaları sırayla çal: önce 1 numaralı karonun üstünde meyve patlat, sonra 2, sonra 3 ve 4. Sırası gelmeyen nota çalmaz.' },
  hazine: { baslik: 'Yeni: Hazine haritası', metin: 'Tahtanın altında görünmeyen hazineler saklı. Her hamleden sonra yaptığın takasın hazineye ne kadar yakın olduğu söylenir: soğuk, ılık, sıcak, çok sıcak. Hazinenin olduğu karede meyve patlatınca bulursun.' },
  kostebek: { baslik: 'Yeni: Köstebek avı', metin: 'Köstebek her hamleden sonra başka bir yuvadan başını çıkarır. Çıktığı karenin hemen yanında ya da üstünde eşleşme yaparsan yakalarsın.' },
  boru: { baslik: 'Yeni: Su boruları', metin: 'Bir borunun yanında eşleşme yapınca boru döner: yatay olur ya da dikey olur. Bir sıradaki bitişik boruların hepsi yatay olunca su akar, borular gider ve o sıra baştan sona temizlenir.' },
  fidan: { baslik: 'Yeni: Filiz ve ağaç', metin: 'Filizin yanında eşleşme yaptıkça filiz büyür: üç eşleşmede ağaç olur. Ağaç her üç hamlede bir yanındaki meyvelerden birini özel meyveye çevirir.' },
  firildak: { baslik: 'Yeni: Rüzgâr fırıldağı', metin: 'Fırıldak her hamleden sonra yön değiştirir: yukarı, sağa, aşağı, sola. Yanında eşleşme yapınca baktığı yöndeki bütün kareleri temizler. Doğru anı bekle!' },
  gunduz: { baslik: 'Yeni: Gece ve gündüz', metin: 'Her dört hamlede bir gün değişir. Sarı güneş çiçekleri yalnız gündüz, mavi ay çiçekleri yalnız gece toplanır: açık çiçeğin üstünde meyve patlat. Başlıktaki güneş ya da ay şimdi hangisi olduğunu gösterir.' },
  ejderha: { baslik: 'Yeni: Ejderha yavrusu', metin: 'Dost ejderha yavrusu her hamleden sonra yanındaki bir kareye yürür. Yanında eşleşme yapınca ateş püskürür ve çevresindeki sekiz kareyi yakar: buzları, kasaları ve kömürleri de!' },
  su: { baslik: 'Yeni: Su basıyor', metin: 'Bahçeyi su basıyor! Suyun altındaki meyve yer değiştiremez. Her üç hamlede bir su her sütunda bir kare yükselir; üstten ikinci satıra ulaşırsa seviye biter. Suyun yanında eşleşme yap ya da pompanın yanında eşleşme yap: pompa kendi satırındaki ve sütunundaki bütün suyu boşaltır.' },
  tirtil: { baslik: 'Yeni: Tırtıl', metin: 'Tırtıllar her iki hamlede bir aşağı iner. En alt sıraya varan tırtıl yaprağı yer ve bir hamlen gider. Tırtılın yanında eşleşme yap: önce koza olur, ikinci eşleşmede kelebek olup uçar.' },
  gizlikapi: { baslik: 'Yeni: Gizli kapılar', metin: 'Tahtanın bazı bölümleri yeşil çitle kapalı. Basınç taşının yanında eşleşme yap ya da özel meyveyle vur: taş çöker, yanındaki kapalı bölüm açılır ve meyvelerle dolar.' },
  mozaik: { baslik: 'Yeni: Mozaik karolar', metin: 'Renkli kenarlı karolar mozaiğin parçaları. Bir karoyu boyamak için karonun rengindeki meyveyi karonun üstünde ya da hemen yanında eşleştir: kırmızı karoya çilek, sarı karoya limon.' },
  miknatis: { baslik: 'Yeni: Mıknatıs', metin: 'Her mıknatısın bir rengi var. Her hamleden sonra o renkteki en yakın meyveyi bir kare çeker; yanına gelen meyveyi yutar. Yanında eşleşme yapmak da mıknatısı doldurur. Beş dolumda mıknatıs patlar ve çevresini temizler.' },
  selale: { baslik: 'Yeni: Şelale', metin: 'Şelaleli sütunlara yukarıdan çoğunlukla aynı renk meyve düşer. Bunu kullanarak alt sıradaki taşların üstünde meyve patlat; her patlama taşı bir kat aşındırır.' },
  karinca: { baslik: 'Yeni: Karınca kervanı', metin: 'Karıncalar yollarında her hamleden sonra bir kare ilerler. Önlerindeki buzlu meyve yolu kapatır: buzları kır, karıncalar yuvaya varsın.' },
  firtina: { baslik: 'Yeni: Fırtına', metin: 'Her dört hamlede bir şimşek çakar ve bir meyveyi kömüre çevirir. Kömürü kırmak için yanında iki kez eşleşme yap. Paratonerin yanında eşleşme yaparsan paratoner dolar; şimşek ona düşer ve bütün sütunu temizler.' },
