  hayalet: { baslik: 'Yeni: Hayalet meyve', metin: 'Hayalet meyve her hamleden sonra görünür ya da kaybolur. Yalnız görünürken eşleşir; görünmezken yerinden oynamaz.' },
  boya: { baslik: 'Yeni: Boya kovası', metin: 'Boya kovasının yanında eşleşme yapınca kova patlar ve çevresindeki meyveleri kendi rengine boyar. Bu, yeni eşleşmeler yaratır.' },
  panayir: { baslik: 'Yeni: Panayır çarkı', metin: 'Her beş hamlede bir panayır çarkı döner. Şansına göre iki meyve özel meyve olur, iki meyve buzlanır ya da puan kazanırsın.' },
